parameter BUSIDLE = 01;
parameter BUSBUSY = 10;

module sequence_first_match;
  logic clk;
  logic frame;
  logic irdy;
  logic[1:0] state;

sequence checkBusIdle;
  (##[2:$] (frame && irdy) );
  //(frame && irdy) [*2:$];
