                    .o_valid  (valid[row][col]       ),
                    .o_sop    (sop  [row][col]       ),
                    .o_eop    (eop  [row][col]       ),
                    .kernel   (kernel[row][col]      ),
                    .ready    (ready[row][col]       ),
                    .cols_cntr(                      ),
                    .rows_cntr(                      )
                );

            end
        end
    endgenerate


    logic [((TRUNK == "TRUE") ? PIX_WIDTH : (PIX_WIDTH+WEIGHT_FRACT_WIDTH))-1:0] sum[OUT_DIMENSION];

    always_comb begin

        foreach (sum[x]) begin
            sum[x] = '0;
        end

        foreach (conv_outputs[x,z]) begin
            sum[x] += $signed(conv_outputs[x][z]);
        end
    end


    always_ff @(posedge clk or negedge rst_n) begin
        if(~rst_n) begin
            o_valid <= 0;
            o_sop   <= 0;
            o_eop   <= 0;
        end else if(clk_en) begin
            o_valid <= valid[0][0];
            o_sop   <= sop[0][0];
            o_eop   <= eop[0][0];

            foreach (o_data[x]) begin
                o_data[x] <= $signed(sum[x]) + $signed(bias[x]);
            end


        end
    end

assign o_ready = ready[0][0];


endmodule : conv_block

        end
    endgenerate



assign o_valid = valid[0];
assign o_sop = sop[0];
assign o_eop   = eop[0];
assign o_ready = ready[0];




endmodule : max_pooling_block

