    parameter                             FRACT_WIDTH        = 5      ,
    parameter                             CONV_NUMB          = 2      ,
    parameter logic [CONV_NUMB-1:0][1:0][7:0]  CONV_DIMENSION     = {{8'd8, 8'd4}, {8'd4, 8'd1}},   
    parameter logic [CONV_NUMB-1:0][ 3:0] KERNEL_DIMENSION   = {4'd3  , 4'd3},
