    parameter                             IMG_HEIGHT         = 28
) (
    input                                clk                     , // Clock
    input                                clk_en                  , // Clock Enable
    input                                rst_n                   , // Asynchronous reset active low
    //input pixels
    input        [  PIX_WIDTH-1:0]       i_data                  ,
    input                                i_valid                 ,
    input                                i_sop                   ,
    input                                i_eop                   ,
    ///
    output logic                         o_valid                 ,
    output logic [CLASSES_QNT-1:0][31:0] classes                 ,
    ///
