genvar numb;
generate
    for (numb = 0; numb < CONV_NUMB; numb++) begin:conv_genloop
        conv_block #(
            .PIX_WIDTH         (PIX_WIDTH                               ),
            .WEIGHT_WIDTH      (WEIGHT_WIDTH                            ),
            .WEIGHT_FRACT_WIDTH(FRACT_WIDTH                             ),
            .TRUNK             ("TRUE"                                  ),
