            .i_sop                   ((numb == 0) ? i_sop   : pool_sop  [numb-1]),
            .i_eop                   ((numb == 0) ? i_eop   : pool_eop  [numb-1]),
            .o_data                  (conv_data [numb]                          ),
            .o_valid                 (conv_valid[numb]                          ),
            .o_sop                   (conv_sop  [numb]                          ),
            .o_eop                   (conv_eop  [numb]                          ),
