logic flat_sop;
logic flat_eop;
logic flat_ready;

    flat #(
        .PIX_WIDTH (PIX_WIDTH                                         ),
        .DIMENSION (CONV_DIMENSION[CONV_NUMB-1][1]                              ),
        .img_width ((IMG_WIDTH - (2**(CONV_NUMB+1)-2))/(2**CONV_NUMB) ),
        .img_height((IMG_HEIGHT - (2**(CONV_NUMB+1)-2))/(2**CONV_NUMB))
    ) inst_flat (
        .clk    (clk                    ),
        .clk_en (clk_en                 ),
