`ifndef AXI_VIP_AXI4PC
  `define AXI_VIP_AXI4PC

interface axi_vip_axi4pc 
  #(int WADDR_WIDTH=32, 
        RADDR_WIDTH=32, 
        WDATA_WIDTH=64, 
        RDATA_WIDTH=64, 
        PROTOCOL = 0,
        RID_WIDTH = 4,
        WID_WIDTH = 4,
        AWUSER_WIDTH=0, 
        WUSER_WIDTH=0, 
        BUSER_WIDTH=0, 
        ARUSER_WIDTH=0,
        RUSER_WIDTH=0,
        MAXRBURSTS=16,
        MAXWBURSTS=16,
        MAXWAITS=64,
        MAXSTALLWAITS=1024,
        RecommendOn=1,
        RecMaxWaitOn=0,
        HAS_ARESETN=1
  ) (
  input bit                               ACLK, 
  input bit                               ACLKEN,
  input bit                               ARESETn,
  input logic [(WADDR_WIDTH-1):0]         AWADDR,
  input logic  [((WID_WIDTH==0) ? 1:WID_WIDTH)-1:0]      AWID,
  input logic [7:0]                       AWLEN,
  input logic [2:0]                       AWSIZE,
  input logic [1:0]                       AWBURST,
  input logic                             AWLOCK,
  input logic [3:0]                       AWCACHE,
  input logic [2:0]                       AWPROT,
  input logic                             AWVALID,
  input logic                             AWREADY,
  input tri1  [((AWUSER_WIDTH==0) ? 1 : AWUSER_WIDTH)-1:0]  AWUSER,
  input logic [3:0]                       AWREGION,
  input logic [3:0]                       AWQOS,

  // write data channel
  input logic                             WLAST,
  input logic [(WDATA_WIDTH-1):0]         WDATA,
  input logic [(WDATA_WIDTH/8)-1:0]       WSTRB,
  input logic                             WVALID,
  input logic                             WREADY,
  input tri1  [((WUSER_WIDTH==0) ? 1 : WUSER_WIDTH)-1:0]    WUSER,

  // write response channel
  input logic [1:0]                       BRESP,
  input logic  [((WID_WIDTH==0) ? 1:WID_WIDTH)-1:0]      BID,
  input logic                             BVALID,
  input logic                             BREADY,
  input tri1  [((BUSER_WIDTH==0) ? 1 : BUSER_WIDTH)-1:0]    BUSER,

  // read address channel
  input logic [(RADDR_WIDTH-1):0]         ARADDR,
  input logic  [((RID_WIDTH==0) ? 1:RID_WIDTH)-1:0]      ARID,
  input logic [7:0]                       ARLEN,
  input logic [2:0]                       ARSIZE,
  input logic [1:0]                       ARBURST,
  input logic                             ARLOCK,
  input logic [3:0]                       ARCACHE,
  input logic [2:0]                       ARPROT,
  input logic                             ARVALID,
  input logic                             ARREADY,
  input tri1  [((ARUSER_WIDTH==0) ? 1 : ARUSER_WIDTH)-1:0]  ARUSER,
  input logic [3:0]                       ARREGION,
  input logic [3:0]                       ARQOS,

  // read data  channel
  input logic  [((RID_WIDTH==0) ? 1:RID_WIDTH)-1:0]      RID,
  input logic                             RLAST,
  input logic [(RDATA_WIDTH-1):0]         RDATA,
  input logic [1:0]                       RRESP,
  input logic                             RVALID,
  input logic                             RREADY,
  input tri1  [((RUSER_WIDTH==0) ? 1 : RUSER_WIDTH)-1:0]    RUSER,
  input tri1                              CACTIVE,
  input tri1                              CSYSREQ,
  input tri1                              CSYSACK

  );

