   // Write Queues

  typedef struct packed {
    bit [7-1:0]     addr;
    bit             excl;
    bit [8-1:0]     len ;
    bit [3-1:0]     size;
    bit [2-1:0]     burst;
    bit [ID_MAX:0]  id;
  } t_cmd_message;

  typedef struct packed {
    bit          [8:0] WCount;  // number of write data stored
    bit                WLast;   // WLAST handshake for 
    bit [(STRB_WIDTH*256)-1:0]  strb;
  } t_wdata_message;

  typedef struct {
    t_cmd_message      cmd;
    t_wdata_message    wdata;
  } t_Wxfer;


  t_Wxfer   WXfer_q [int][$];

  //W-Tranfer internals 
  t_Wxfer   Wtrasfer;
  t_cmd_message AW_q[$];
  t_wdata_message w_channel_q[$];
  t_cmd_message AWCmd;
  t_wdata_message Wburst;
  t_Wxfer   WXfer;
  int unsigned Woutstanding = 0;
  integer unsigned wid_q[$];
  integer unsigned first_beat  = 1;
  integer unsigned wdata_q_entries = 0;
  integer unsigned map_id;

  typedef struct packed {
    t_cmd_message       cmd;
    bit          [8:0]  Count;
  } t_rburst_xfer;

  t_rburst_xfer RXfer_q[int][$];

  //R-Tranfer internals 
  t_rburst_xfer ARCmd;
  t_rburst_xfer RXfer;
  int unsigned Routstanding = 0;
  reg rvalid = 'b0;
  reg rready = 'b0;
  reg [(RDATA_WIDTH-1):0]  Rdata = 'b0;

  reg          [6:0] AlignMaskR; // mask for checking read address alignment
  reg          [6:0] AlignMaskW; // mask for checking write address alignment

  // signals for Address Checking
  reg   [RADDR_MAX:0] ArAddrIncr;
  reg   [WADDR_MAX:0] AwAddrIncr;

  // signals for Data Checking
  reg  [RDATA_MAX:0] RdataMask = 'b0;
  reg  [WDATA_MAX:0] WdataMask;
  reg         [10:0] ArSizeInBits;
  reg         [10:0] AwSizeInBits;

  typedef struct packed {
    bit                ReadData; // tracks excl read data
    bit   [ADDR_MAX:0] Addr;
    bit          [2:0] Size;
    bit          [7:0] Len;
    bit          [1:0] Burst;
    bit          [3:0] Cache;
    bit          [2:0] Prot;
    bit          [3:0] Qos;
    bit          [3:0] Region;
    bit [AWUSER_MAX:0] User;
  } t_exclsive_xfer;

  t_exclsive_xfer Excl_Xfer[int];

  t_exclsive_xfer RExcl;
  int        ArLenInBytes;
  reg [14:0] ExclMask = 'b1;   // mask to check alignment of exclusive address


  // Signals to avoid feeding parameters directly into assertions as this can
  // stop assertions triggering in some cases
  reg                i_RecommendOn;
  reg                i_RecMaxWaitOn;

  function void set_recommendon();
    i_RecommendOn = 1;
  endfunction : set_recommendon

  function void clr_recommendon();
    i_RecommendOn = 0;
  endfunction : clr_recommendon

  function bit get_recommendon();
    return(i_RecommendOn);
  endfunction : get_recommendon

  function void set_recmaxwaiton();
    i_RecMaxWaitOn = 1;
  endfunction : set_recmaxwaiton

  function void clr_recmaxwaiton();
    i_RecMaxWaitOn = 0;
  endfunction : clr_recmaxwaiton

  function bit get_recmaxwaiton();
    return(i_RecMaxWaitOn);
  endfunction : get_recmaxwaiton

