   `ARM_AMBA4_PC_MSG_WARN("%m : AWADDR=0x%0x, AWID=0x%x, AWLEN=0x%x, AWSIZE=0b%b", AWADDR, AWID, AWLEN, AWSIZE);
   `ARM_AMBA4_PC_MSG_ERR(`ERRM_AWLEN_WRAP);
  end


