  endproperty
  axi4_errm_arlen_wrap: assert property (AXI4_ERRM_ARLEN_WRAP) else begin
   `ARM_AMBA4_PC_MSG_WARN("%m : ARADDR=0x%0x, ARID=0x%x, ARLEN=0x%x, ARSIZE=0b%b", ARADDR, ARID, ARLEN, ARSIZE);
