/*
    This module synchronizes a pulse to a destination domain,
    as well for high to low or low to high freq. It provides
    back a ready signal to avoid losing a pulse.
*/

module hsk_pulse_synchro

    (
    input  wire aclk_i,
    input  wire arstn_i,
    input  wire aclk_o,
    input  wire arstn_o,
    input  wire tvalid_i,
    output wire tready_i,
    output reg  tvalid_o
    );

