            pulse_mux_sync_ffd <= 1'b0;
            tvalid_o <= 1'b0;
        end
        else begin
            pulse_mux_sync_ffd <= pulse_mux_sync;
            tvalid_o <= pulse_passed_in_dest;
        end

    end

endmodule

