    `define fp_qw(fp) ($bits(fp.dummy_qw)-1)
    `define fp_wl(fp) ($bits(fp.dummy_wl)-1)
    `define fp_iw(fp) (`fp_wl(fp)-`fp_qw(fp)) // doing this instead of ($bits(fp.dummy_iw)-1) to allow negative iw

