                s_RREADY    =   m1_RREADY;
            end
            4'b0010: begin
                s_ARID      =   m2_ARID;
                s_ARADDR    =   m2_ARADDR;
                s_ARLEN     =   m2_ARLEN;
                s_ARSIZE    =   m2_ARSIZE;
                s_ARBURST   =   m2_ARBURST;
                s_ARLOCK    =   m2_ARLOCK;
                s_ARCACHE   =   m2_ARCACHE;
                s_ARPROT    =   m2_ARPROT;
                s_ARQOS     =   m2_ARQOS;
                s_ARREGION  =   m2_ARREGION;
                s_ARUSER    =   m2_ARUSER;
                s_ARVALID   =   m2_ARVALID;
                s_RREADY    =   m2_RREADY;
            end
            4'b0001: begin
                s_ARID      =   m3_ARID;
                s_ARADDR    =   m3_ARADDR;
                s_ARLEN     =   m3_ARLEN;
                s_ARSIZE    =   m3_ARSIZE;
                s_ARBURST   =   m3_ARBURST;
                s_ARLOCK    =   m3_ARLOCK;
                s_ARCACHE   =   m3_ARCACHE;
                s_ARPROT    =   m3_ARPROT;
                s_ARQOS     =   m3_ARQOS;
                s_ARREGION  =   m3_ARREGION;
                s_ARUSER    =   m3_ARUSER;
                s_ARVALID   =   m3_ARVALID;
                s_RREADY    =   m3_RREADY;
            end
            default: begin
                s_ARID      =   '0;
                s_ARADDR    =   '0;
                s_ARLEN     =   '0;
                s_ARSIZE    =   '0;
                s_ARBURST   =   '0;
                s_ARLOCK    =   '0;
                s_ARCACHE   =   '0;
                s_ARPROT    =   '0;
                s_ARQOS     =   '0;
                s_ARREGION  =   '0;
                s_ARUSER    =   '0;
                s_ARVALID   =   '0;
                s_RREADY    =   '0;
            end

        endcase
    end

    //---------------------------------------------------------
    //ARREADY信号复用
    always_comb begin
        case({m0_rgrnt,m1_rgrnt,m2_rgrnt,m3_rgrnt})
            4'b1000: begin
                m0_ARREADY  = m_ARREADY;
                m1_ARREADY  = '0;
                m2_ARREADY  = '0;
                m3_ARREADY  = '0;
            end
            4'b0100: begin
                m0_ARREADY  = '0;
                m1_ARREADY  = m_ARREADY;
                m2_ARREADY  = '0;
                m3_ARREADY  = '0;
            end
            4'b0010: begin
                m0_ARREADY  = '0;
                m1_ARREADY  = '0;
                m2_ARREADY  = m_ARREADY;
                m3_ARREADY  = '0;
            end
            4'b0001: begin
                m0_ARREADY  = '0;
                m1_ARREADY  = '0;
                m2_ARREADY  = '0;
                m3_ARREADY  = m_ARREADY;
            end

right_context:
                m0_ARREADY  = '0;
                m1_ARREADY  = '0;
                m2_ARREADY  = '0;
                m3_ARREADY  = '0;
            end
        endcase
    end

    //---------------------------------------------------------
    //RVALID信号复用
    always_comb begin
        case({m0_rgrnt,m1_rgrnt,m2_rgrnt,m3_rgrnt})
            4'b1000: begin
                m0_RVALID  = m_RVALID;
                m1_RVALID  = '0;
                m2_RVALID  = '0;
                m3_RVALID  = '0;
            end
            4'b0100: begin
                m0_RVALID  = '0;
                m1_RVALID  = m_RVALID;
                m2_RVALID  = '0;
                m3_RVALID  = '0;
            end
            4'b0010: begin
                m0_RVALID  = '0;
