                m2_RVALID  = '0;
                m3_RVALID  = m_RVALID;
            end
            default: begin
                m0_RVALID  = '0;
                m1_RVALID  = '0;
                m2_RVALID  = '0;
                m3_RVALID  = '0;
            end
        endcase
    end

endmodule

