                      .ID_BITS(ID_BITS),
                      .INTPRIORITY_BITS(INTPRIORITY_BITS)) cmp_l1 (
                      .a_id(level_intpend_id[0][2*m]),
                      .a_priority(level_intpend_w_prior_en[0][2*m]),
                      .b_id(level_intpend_id[0][2*m+1]),
