   always_comb begin 
      m_axis_tready_all = 0;

      // route master ready back to chosen slave
      if (current_state == WRITING) begin
         m_axis_tready_all[channel_choice] = m_axis_tready;

      end
      else begin
         m_axis_tready_all[channel_choice] = 0;

