      .m_axis_tvalid(M_AXIS_TVALID),            // output wire m_axis_tvalid
      .m_axis_tready(M_AXIS_TREADY),            // input wire m_axis_tready
      .m_axis_tdata(M_AXIS_TDATA),              // output wire [7 : 0] m_axis_tdata
