//This file handles the communication between the memory controller and the \
//Cache BFM with respect to the data read by the controller from the memory.
//Send_read_data is used by the controller
//receive_read_data is used by the cache bfm
//Author: Niraj Thakkar
module send_read_data  
(	
	C2MInterface.Mem_data IF, 
	input logic internal_ready,
				[IF.DWIDTH-1:0]data_in, 
				[2:0] tag_gen
);

assign IF.read_data = (internal_ready)?data_in:'z;
assign IF.tag_data = (internal_ready)?tag_gen:'z;
assign IF.valid_data = internal_ready;

endmodule

module receive_read_data  
(C2MInterface.Cache_data IF,output logic read_valid, [IF.DWIDTH-1:0] data_out,[2:0] tag_out);

assign data_out = IF.read_data;
assign tag_out = IF.tag_data;

//This module is used by the Memory controller to receive commands from the Cache
//Author: Niraj Thakkar
module receive_command 
(
	C2MInterface.Mem_tran IF,
	input logic fifo_full, [2:0] tag_gen,
	output logic 	rw_out, valid,
					[IF.AWIDTH-1:0] addr_out,
					[IF.DWIDTH-1:0]data_out
);

logic [IF.DWIDTH-1:0] data;
logic [IF.AWIDTH-1:0] addr;
logic [2:0] tag;
logic rw;
logic full;
logic ack;

assign valid = IF.ack_tran;

//Enumerated types of States
typedef enum logic [1:0] {init=2'b01,receive=2'b10}st;
st state,next_state;

//Sequential Logic
always_ff @(posedge IF.clock)
begin
	data_out<=data;
	addr_out<=addr;
	rw_out<=rw;

if(IF.reset)
	state<=init;
else begin

right_context:
	case(state)
	init:	if(fifo_full || !IF.valid_tran)
				next_state=init;
		 	else
				next_state=receive;

	receive: if(fifo_full || IF.valid_tran)
				next_state=init;
			 else
				next_state=receive;
	endcase
end

always_comb
begin
	case(state)
	init:
		begin
		if(fifo_full)
			IF.full=1;
		else
			IF.full=0;
		addr=IF.addr; data=IF.data_tran;
		rw=IF.rw; IF.ack_tran=0;
		tag=tag_gen;
		end
	receive:
		begin
		full=0;
		addr=IF.addr;
		rw=IF.rw;
		IF.ack_tran=1;
		IF.tag_tran=tag_gen;
		data=IF.data_tran;
		end
	endcase
end

endmodule

