    typedef logic [15:0] reg16_t;  // Timer counter, timer latch
    typedef logic  [7:0] reg8_t;   // Data bus, register bytes
    typedef logic  [3:0] reg4_t;   // Address bus, BCD count
    typedef logic  [2:0] reg3_t;   // BCD count
