    typedef struct packed {
        struct packed {
            reg4_t zero;
            reg4_t t;
        } tod_10ths;
        struct packed {
            logic zero;
            reg3_t sh;
            reg4_t sl;
        } tod_sec;
        struct packed {
            logic zero;
            reg3_t mh;
            reg4_t ml;
        } tod_min;
        struct packed {
            logic pm;
            reg2_t zero;
            logic  hh;
            reg4_t hl;
        } tod_hr;
    } tod_t;

    typedef struct packed {
        logic ir_s_c;
        logic z7;
        logic z6;
        logic flg;
        logic sp;
        logic alrm;
        logic tb;
        logic ta;
    } icr_t;

    typedef struct packed {
