    input  bit rst,
    input  bit ena,
    input  bit [WIDTH-1:0] data_in ,
    output bit [WIDTH-1:0] data_out
);
    bit [WIDTH-1:0] r_data;

    always_ff @(posedge clk) begin
        if(ena) begin
            r_data <= data_in ;
            data_out <= r_data - data_in ;
        end

right_context:
);

    always_ff @(posedge clk) begin
        if(ena) begin
            data_out <= data_out + data_in ;
