                else
                    RNext_state_M = R_START_M;	
            end

   R_READ_M:begin
                RNext_state_M = R_VALID_M;
                axim.RREADY= '1;        //setting RREADY to 1 to say to slave that master is ready to receive valid data.

                case(arburst)
                  2'b00:begin
