    bit[7:0] id;
    axi_transaction#(D_WIDTH, A_WIDTH) trans;
    test_config test_cfg;

    //  Constructor: new
    function new(string name = "axi_read_seq");
        super.new(name);

right_context:
            `uvm_fatal(get_name(), "config cannot be found in ConfigDB!")

        no_of_trans = test_cfg.no_read_cases;
    endfunction: new

