(* shreg_extract = "no", ASYNC_REG = "TRUE" *) FD #( .INIT (1'b0) ) rxpmaresetdone_sync1 ( .C(DRPCLK_IN), .D(rxpmaresetdone0), .Q(rxpmaresetdone1) );

