//    .probe7  ( rx_dword                ),
//    .probe8  ( rx_dword_en             ),
//    .probe9  ( rx_dword_prim           ),
//    .probe10 ( rx_dword                ),
//    .probe11 ( tx_prim2                ),
//    .probe12 ( tx_data2                )
//);


endmodule

