`timescale 1 ns / 1 fs

module ACounter(
      clk,
      Res,
      Set835,
      CntEn ,
      CntOut,
      TC2048,
      TC3
   )/*synthesis ugroup="addr_group" */;

right_context:
   input CntEn;
   output [11:0]  CntOut;
   output  reg TC2048;
   output  reg TC3;

reg [11:0] cnt_state;

always@(posedge clk)
  if (Res)
    cnt_state <= 0;
  else if (Set835)
    cnt_state <=12'h835;   
  else if (CntEn)
    cnt_state <= cnt_state + 1;


always@(cnt_state)
   if (cnt_state== 12'h7FF) begin
      TC2048 <= 1; 
      TC3 <=0;
   end else if (cnt_state[7:0] == 8'h40) begin
     TC3 <= 1; 
     TC2048 <= 0;
   end
  // --elsif (cnt_state(3 downto 0) = x"7") or 
  // --      (cnt_state(3 downto 0) = x"A") or 
  // --      (cnt_state(3 downto 0) = x"D") then
  // --  TC3 <= '1'; TC2048 <= '0';
   else begin
     TC3 <=0;
     TC2048 <= 0;
   end


assign CntOut = cnt_state;

endmodule

