/************************************* stress test *********************************************/
task stress_test;

	//5 consecutive writes from same block and consecutive pages
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c1);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c2);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c3);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c4);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c5);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h00c6);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//5 consecutive reads with same block and consecutive reads
	@(posedge bfm.clk);
	read_cycle(16'h00c1);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h00c2);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h00c3);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h00c4);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h00c5);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	// Write's to pages in different blocks
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0041);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0008);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;


	// Read's from pages in different blocks
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0041);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0008);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	// write's to random pages in same block
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0043);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0049);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//read's to random pages in same block
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0043);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0049);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	// Erase to page program
	kill(10);
	erase_cycle(16'h00c8);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0246);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//reset to program page
	kill(10);
	reset_cycle();
	repeat(10)@(posedge bfm.clk);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0042);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//page program to erase
	kill(10);
	erase_cycle(16'h0042);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//read to program page 
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0042);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0043);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//page program to read_id
	kill(10);
	read_id_cycle();
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//Write and Read from first and last location in memory
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h0000);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//Read from first location
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h0000);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//Write and read from last location
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'h03FF);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//Read from last location
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'h03FF);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//back to back reset
	kill(10);
	reset_cycle();
	repeat(10)@(posedge bfm.clk);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	reset_cycle();
	repeat(10)@(posedge bfm.clk);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//back to back erase
	kill(10);
	erase_cycle(16'h0000);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	erase_cycle(16'h03FF);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;
endtask
/***********************************************************************************************/

/************************************* cross task **********************************************/
task Cross;
	// Commands with System Reset at the same time
	// System reset with write command
	kill(10); 
	@(posedge bfm.clk);
        write_cycle(16'hxxxx);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	//System reset with read_page command
	kill(10);
	bfm.rst= 1'b1;
	read_cycle(16'h00c8);
	bfm.rst= 1'b0;

	// System Reset with Erase command
	kill(10);
	bfm.rst= 1'b1;
	erase_cycle(16'h00c5);
	bfm.rst= 1'b0;

	//System Reset with reset command
	kill(10);
	bfm.rst= 1'b1;
	reset_cycle();
	bfm.rst= 1'b0;

	//System Reset with Read_id command
	kill(10);
	bfm.rst= 1'b1;
	read_id_cycle();
	bfm.rst= 1'b0;

	// System Reset with Invalid command
	kill(10);
	bfm.rst= 1'b1;
	Invalid_Cmd();
	bfm.rst= 1'b0;

	// Invalid Row Address with Write Command
	kill(10); 
	@(posedge bfm.clk);
	write_cycle(16'hxxxx);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	// Invalid Row Address with Read Command
	kill(10); 
	@(posedge bfm.clk);
	read_cycle(16'hxxxx);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	// Invalid Row Address with Erase command
	kill(10);
	erase_cycle(16'hxxxx);
        wait(bfm.nfc_done);
        @(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

endtask : Cross
/***********************************************************************************************/

/*********************************** basic operations ******************************************/
task basic_operations;
	write_cycle(16'h00c8);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	read_cycle(16'h00c8);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;
	//read_buffer();

	kill(10);
	write_cycle(16'h00c7);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	erase_cycle(16'h00c8);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	reset_cycle();
	repeat(10)@(posedge bfm.clk);
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;

	kill(10);
	read_id_cycle();
	wait(bfm.nfc_done);
	@(posedge bfm.clk) ;
   	bfm.nfc_cmd=3'b111;
endtask
/***********************************************************************************************/

/************************************ Commands task ********************************************/
task Invalid_Cmd();
	bfm.send(3'b000, 16'h0000);
endtask

task write_cycle(input logic [15:0]addr);
	bfm.send(3'b001,addr);
	for(int i=0; i<2048; i++) begin
		memory[i]=$random % 256; 
		bfm.write_buffer(1'b1,memory[i],i);
	end
endtask

task read_data();
	for(int i=0; i<2048; i++) begin
		bfm.read_buffer(i);
	end
endtask

task read_cycle(input bit [15:0]addr);
	bfm.send(3'b010,addr);
endtask

task erase_cycle(input bit [15:0]addr);
	bfm.send(3'b100,addr);
endtask

task reset_cycle();
	bfm.send(3'b011,16'h1234);
endtask

task read_id_cycle();
	bfm.send(3'b101,16'h0000);
endtask
/***********************************************************************************************/

/************************************ Kill time task *******************************************/
task kill(input int i);
	repeat(i)@(posedge bfm.clk);		
endtask
/***********************************************************************************************/
