  task slave_rdata (input tx_t tx, input int i);
    slave_cb.rid    <= tx.txid;
    slave_cb.rdata  <= tx.data[i].data;
    slave_cb.rresp  <= OKAY;
    slave_cb.rlast  <= (i == tx.addr.len);
    slave_cb.rvalid <= 1'b1;
    @(slave_cb);

    wait (slave_cb.rready == 1'b1);
    slave_cb.rid    <= '0;
    slave_cb.rdata  <= '0;
    slave_cb.rresp  <= OKAY;
    slave_cb.rlast  <= 1'b0;
    slave_cb.rvalid <= 1'b0;
  endtask

  task monitor_start ();
    monitor_clear();
    fork
      forever begin
        monitor_reset();
      end
    join_none
  endtask

  task monitor_reset ();
    wait (areset_n == 1'b0);
    monitor_clear();
    wait (areset_n == 1'b1);
  endtask

  task monitor_clear ();
