  virtual protected task check_rdata ();
    hold_rdata_t now = '{
      rid   : axi.monitor_cb.rid,
      rdata : axi.monitor_cb.rdata,
      rresp : axi.monitor_cb.rresp,
      rlast : axi.monitor_cb.rlast,
