// PB0-PB6 = sub0
// PB7-13 =  sub1
// PB14-20 = sub2
// PB21-27 = sub3

// returns number of non-zero elements in array
function int check_non_zero_elem(logic [7:0] a0[]);
    check_non_zero_elem = 0;
    for(int i=$low(a0); i <= $high(a0); i++)
