    logic [7:0] axi_awlen_q;
    logic [2:0] axi_awprot_q;
    logic [AXI_ID_WIDTH-1:0] axi_awid_q;
    logic [AXI_ADDRESS_WIDTH-1:0] axi_awaddr_q;

