                wdata_shiftreg = dmem_req_uw_data;
                axi_wstrb = dmem_req_uw_strb;
                write_state = W_IOSTORE;
            end
        end

        if (reset) begin
            axi_awvalid = 0;
            wvalid_counter = 0;
            write_state = W_IDLE;
        end
    end

