  "zeros":  init_val[i] = {DataWidth{1'b0}};
  "ones":   init_val[i] = {DataWidth{1'b1}};
  "random": init_val[i] = {DataWidth{$urandom()}};
  default:  init_val[i] = {DataWidth{1'bx}};
endcase

